  @Nested
  @DisplayName("allowEmptyValue query params")
  class AllowEmptyValueQueryParams {

    @Test
    @DisplayName("null options omits allowEmptyValue param")
    /* This regression test deliberately passes null to a @NonNull parameter
     * to assert the URL omits the param. Passing null is the exact thing
     * NullAway forbids, so the violation is intrinsic to what the test
     * verifies and cannot be refactored away. It cannot move to a global
     * config home without either excluding all error-prone checks from the
     * test sources (-XepExcludedPaths) or disabling NullAway on tests
     * wholesale, both of which would drop real null-safety coverage from the
     * test tree; the suppression is therefore kept, scoped to this one
     * intentionally-null-passing test method. */
    @SuppressWarnings("NullAway")
    void bhvOptions002NullOptionsOmitsAllowEmptyValueParam() {
      var client = new CapturingApiClient();
      var config = new Configuration("http://localhost", Map.of());
      var api = new PetApi(client, config);
      try {
        api.findPetsByStatus(null);
      } catch (Exception ignored) {
        // Response deserialization may fail; we only care about the captured URL
      }
      assertFalse(
          client.capturedUrl.contains("status="),
          "Expected no status param when options is null, got: " + client.capturedUrl);
    }

    @Test
    @DisplayName(
        "bhvSerializationWire001 allowEmptyValue param omitted when value is null in options")
    void bhvSerializationWire001AllowEmptyValueOmittedWhenNull() {
      var client = new CapturingApiClient();
      var config = new Configuration("http://localhost", Map.of());
      var api = new PetApi(client, config);
      try {
        api.findPetsByStatus(new FindPetsByStatusOptions());
      } catch (Exception ignored) {
        // Response deserialization may fail; we only care about the captured URL
      }
      // A null optional allowEmptyValue value must NOT emit a spurious empty key;
      // the key is sent only when the caller supplies a value (see the next test).
      assertFalse(
          client.capturedUrl.contains("status="),
          "Expected no status= for allowEmptyValue param with null value, got: "
              + client.capturedUrl);
    }

    @Test
    @DisplayName("bhvOperations003 allowEmptyValue param included when value is empty string")
    void bhvOperations003AllowEmptyValueIncludedWhenEmpty() {
      var client = new CapturingApiClient();
      var config = new Configuration("http://localhost", Map.of());
      var api = new PetApi(client, config);
      try {
        api.findPetsByStatus(new FindPetsByStatusOptions().status(""));
      } catch (Exception ignored) {
        // Response deserialization may fail; we only care about the captured URL
      }
      assertTrue(
          client.capturedUrl.contains("status="),
          "Expected status= in URL for empty string allowEmptyValue param, got: "
              + client.capturedUrl);
    }
  }

  @Nested
  @DisplayName("per-call options")
  class PerCallOptions {

    /** A client that records the per-call overrides it is handed. */
    static class OverrideCapturingClient extends CapturingApiClient {
      @Nullable Integer capturedTimeout;
      @Nullable Integer capturedRetries;
      boolean overrideOverloadUsed;

      @Override
      public ApiHttpResponse sendRequest(
          String method,
          String url,
          Map<String, String> headers,
          @Nullable Object body,
          @Nullable Integer timeoutMillis,
          @Nullable Integer maxRetries) {
        this.overrideOverloadUsed = true;
        this.capturedTimeout = timeoutMillis;
        this.capturedRetries = maxRetries;
        return sendRequest(method, url, headers, body);
      }
    }

    private PetApi apiOver(ApiClient client) {
      return new PetApi(client, new Configuration("http://localhost", Map.of()));
    }

    @Test
    @DisplayName("bhvTransport002 the timeout reaches the transport for this call only")
    void bhvTransport002TimeoutReachesTheTransportForThisCallOnly() {
      var client = new OverrideCapturingClient();
      var api = apiOver(client);
      try {
        api.findPetsByStatus(new FindPetsByStatusOptions().timeout(1500));
      } catch (Exception ignored) {
        // Response deserialization may fail; we only care about what the transport saw
      }
      assertEquals(1500, client.capturedTimeout);
      client.overrideOverloadUsed = false;
      client.capturedTimeout = null;
      try {
        api.findPetsByStatus(new FindPetsByStatusOptions());
      } catch (Exception ignored) {
        // Response deserialization may fail; we only care about what the transport saw
      }
      assertFalse(client.overrideOverloadUsed);
      assertNull(client.capturedTimeout);
    }

    @Test
    @DisplayName("bhvRetries009 timeout and maxRetries reach the transport")
    void bhvRetries009TimeoutAndRetriesReachTheTransport() {
      var client = new OverrideCapturingClient();
      try {
        apiOver(client).findPetsByStatus(new FindPetsByStatusOptions().timeout(1500).maxRetries(0));
      } catch (Exception ignored) {
        // Response deserialization may fail; we only care about what the transport saw
      }
      assertTrue(client.overrideOverloadUsed);
      assertEquals(1500, client.capturedTimeout);
      assertEquals(0, client.capturedRetries);
    }

    @Test
    @DisplayName("without per-call settings the plain send is used")
    void withoutPerCallSettingsThePlainSendIsUsed() {
      var client = new OverrideCapturingClient();
      try {
        apiOver(client).findPetsByStatus(new FindPetsByStatusOptions());
      } catch (Exception ignored) {
        // Response deserialization may fail; we only care about what the transport saw
      }
      assertFalse(client.overrideOverloadUsed);
    }

    @Test
    @DisplayName("headers are sent with the call")
    void headersAreSentWithTheCall() {
      var client = new CapturingApiClient();
      try {
        apiOver(client)
            .findPetsByStatus(new FindPetsByStatusOptions().headers(Map.of("X-Trace", "abc")));
      } catch (Exception ignored) {
        // Response deserialization may fail; we only care about the captured headers
      }
      assertEquals("abc", client.capturedHeaders.get("X-Trace"));
    }

    @Test
    @DisplayName("bhvOperations001 a per-call header replaces a default header of the same name")
    void bhvOperations001PerCallHeaderReplacesADefault() {
      var client = new CapturingApiClient();
      var api =
          new PetApi(client, new Configuration("http://localhost", Map.of("X-Trace", "default")));
      try {
        api.findPetsByStatus(new FindPetsByStatusOptions().headers(Map.of("X-Trace", "call")));
      } catch (Exception ignored) {
        // Response deserialization may fail; we only care about the captured headers
      }
      assertEquals("call", client.capturedHeaders.get("X-Trace"));
    }

    @Test
    @DisplayName(
        "bhvOperations096 an operation with no parameters and no security takes the per-call"
            + " settings")
    void bhvOperations096AnOperationWithNothingElseTakesThePerCallSettings() {
      var client = new OverrideCapturingClient();
      var api = new StoreApi(client, new Configuration("http://localhost", Map.of()));
      try {
        api.getInventory(
            new GetInventoryOptions()
                .timeout(1500)
                .maxRetries(0)
                .headers(Map.of("X-Trace", "abc")));
      } catch (Exception ignored) {
        // Response deserialization may fail; we only care about what the transport saw
      }
      assertTrue(client.overrideOverloadUsed);
      assertEquals(1500, client.capturedTimeout);
      assertEquals(0, client.capturedRetries);
      assertEquals("abc", client.capturedHeaders.get("X-Trace"));
    }

    @Test
    @DisplayName(
        "bhvAuthIntegration011 an operation with no parameters and no security still works without"
            + " options")
    void bhvAuthIntegration011AnOperationWithNothingElseWorksWithoutOptions() {
      var client = new OverrideCapturingClient();
      var api = new StoreApi(client, new Configuration("http://localhost", Map.of()));
      try {
        api.getInventory();
      } catch (Exception ignored) {
        // Response deserialization may fail; we only care about what the transport saw
      }
      assertFalse(client.overrideOverloadUsed);
    }

    @Test
    @DisplayName("an invalid timeout or retry count is refused")
    void anInvalidTimeoutOrRetryCountIsRefused() {
      assertThrows(IllegalArgumentException.class, () -> new FindPetsByStatusOptions().timeout(0));
      assertThrows(
          IllegalArgumentException.class, () -> new FindPetsByStatusOptions().maxRetries(-1));
      assertThrows(IllegalArgumentException.class, () -> new GetInventoryOptions().timeout(0));
      assertThrows(IllegalArgumentException.class, () -> new GetInventoryOptions().maxRetries(-1));
    }
  }

